        if s in F:
            if F[s] != t:
                print(-1)
                return
        else:
            F[s] = t

    A = set(S)
    image = set(F.values())

    # Impossible case: |A|=26 and image covers all 26 letters (non-identity permutation)
    if len(A) == 26 and len(image) == 26:
        print(-1)
        return

    edges = sum(1 for c in A if F[c] != c)

    processed = set()
    cycles = 0
    for start in A:
        if start in processed:
            continue
        path = []
        on_path = set()
        cur = start
        while True:
            if cur not in A or F[cur] == cur:
                break
            if cur in processed:
                break
            if cur in on_path:
                cycles += 1
                break
            on_path.add(cur)
            path.append(cur)
            cur = F[cur]
        for p in path:
            processed.add(p)

    print(edges + cycles)

solve()

